import React, { useState } from 'react';
import { sendEnquiry } from '../services/api';
import { useAuth } from '../context/AuthContext';
import { X } from 'lucide-react';
import styles from './EnquiryModal.module.css';

export default function EnquiryModal({ property, onClose }) {
  const { user } = useAuth();
  const [form, setForm] = useState({
    name:    user?.name    || '',
    email:   user?.email   || '',
    phone:   user?.phone   || '',
    message: `I am interested in "${property?.title}". Please get in touch with me.`,
  });
  const [loading, setLoading] = useState(false);
  const [sent,    setSent]    = useState(false);
  const [error,   setError]   = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await sendEnquiry({ propertyId: property.id || property._id, ...form });
      setSent(true);
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to send. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.overlay} onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className={styles.modal}>
        <div className={styles.header}>
          <h2 className={styles.title}>Send Enquiry</h2>
          <button className={styles.closeBtn} onClick={onClose}><X size={20} /></button>
        </div>

        {property && (
          <div className={styles.propSnippet}>
            <img
              src={property.image || (property.images?.[0]) || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=400&q=70'}
              alt={property.title}
              className={styles.propImg}
            />
            <div>
              <div className={styles.propTitle}>{property.title}</div>
              <div className={styles.propPrice}>{property.price}</div>
              <div className={styles.propLoc}>{property.location}</div>
            </div>
          </div>
        )}

        {sent ? (
          <div className={styles.success}>
            <div className={styles.successIcon}>🎉</div>
            <div className={styles.successTitle}>Enquiry Sent!</div>
            <div className={styles.successSub}>The property owner will contact you shortly.</div>
            <button className={styles.doneBtn} onClick={onClose}>Done</button>
          </div>
        ) : (
          <form className={styles.form} onSubmit={handleSubmit}>
            {error && <div className={styles.error}>{error}</div>}
            <div className={styles.row}>
              <div className={styles.field}>
                <label className={styles.label}>Name</label>
                <input type="text" className={styles.input} value={form.name}
                  onChange={e => setForm(f => ({ ...f, name: e.target.value }))} required />
              </div>
              <div className={styles.field}>
                <label className={styles.label}>Phone</label>
                <input type="tel" className={styles.input} value={form.phone}
                  onChange={e => setForm(f => ({ ...f, phone: e.target.value }))} />
              </div>
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Email</label>
              <input type="email" className={styles.input} value={form.email}
                onChange={e => setForm(f => ({ ...f, email: e.target.value }))} required />
            </div>
            <div className={styles.field}>
              <label className={styles.label}>Message</label>
              <textarea rows={4} className={styles.textarea} value={form.message}
                onChange={e => setForm(f => ({ ...f, message: e.target.value }))} required />
            </div>
            <button type="submit" className={styles.submitBtn} disabled={loading}>
              {loading ? 'Sending…' : 'Send Enquiry'}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}
